import csv
import re
from datetime import datetime, date
from io import BytesIO, StringIO
from zipfile import ZipFile, BadZipFile

import pandas as pd

FIELDS = {
    'period': 'Date / month', 'revenue': 'Net sales revenue',
    'cogs': 'Cost of goods / ingredients', 'payroll': 'Payroll including employer costs',
    'rent': 'Occupancy / rent', 'other': 'Other operating costs', 'amount': 'Amount',
}
COSTS = ['cogs', 'payroll', 'rent', 'other']
FINANCIAL = ['revenue'] + COSTS
ALIASES = {
    'period': ['date', 'month', 'period', 'reporting month', 'transaction date', 'sale date', 'invoice date', 'posting date', 'accounting period'],
    'revenue': ['revenue', 'sales', 'net sales', 'net revenue', 'sales revenue', 'turnover', 'monthly sales', 'net takings'],
    'cogs': ['cogs', 'cost of goods', 'cost of goods sold', 'cost of sales', 'ingredients', 'food cost', 'ingredient costs'],
    'payroll': ['payroll', 'wages', 'staff cost', 'staff costs', 'labour costs', 'labor costs', 'salaries', 'employee costs'],
    'rent': ['rent', 'occupancy', 'occupancy costs', 'lease expense', 'premises cost'],
    'other': ['other expenses', 'other costs', 'other operating costs', 'overheads', 'operating overhead'],
    'amount': ['amount', 'value', 'net amount', 'transaction amount', 'total amount', 'paid amount'],
}


def normalise(value):
    value = re.sub(r'([a-z])([A-Z])', r'\1 \2', str(value))
    value = re.sub(r'\b(cad|usd|gbp|eur)\b', '', value.lower())
    return re.sub(r'[^a-z0-9]+', ' ', value).strip()


def table_hint(name):
    """Reviewable defaults from familiar table names; not inferred accounting truth."""
    words=set(normalise(name).split())
    for field,terms in [('cogs',{'ingredient','ingredients','supplier','purchases','cogs'}),
                        ('payroll',{'payroll','wages','salaries'}),
                        ('rent',{'occupancy','premises','rent'}),
                        ('other',{'expenses','operating','overhead'})]:
        if words & terms:
            return 'Expense transactions',field
    if words & {'sales','pos','receipts'}:
        return 'Sales transactions','other'
    return 'Monthly summary','other'


def suggestions(frame, fields):
    """Exact normalized synonyms only. Competing candidates require a human choice."""
    result, evidence = {}, []
    for field in fields:
        matches = [c for c in frame.columns if normalise(c) in ALIASES[field]]
        chosen = matches[0] if len(matches) == 1 else None
        result[field] = chosen
        evidence.append({'Field': FIELDS[field], 'Suggested column': chosen or 'Choose manually',
                         'Reason': 'Recognised heading synonym' if chosen else 'Multiple candidates: ' + ', '.join(matches) if matches else 'No confident heading match',
                         'Examples': ', '.join(str(x)[:40] for x in frame[chosen].head(3)) if chosen else ''})
    return result, pd.DataFrame(evidence)


def sheet_names(content):
    if not content or len(content) > 20 * 1024 * 1024:
        raise ValueError('Choose a non-empty file under 20 MB.')
    try:
        with ZipFile(BytesIO(content)) as archive:
            if sum(i.file_size for i in archive.infolist()) > 100 * 1024 * 1024:
                raise ValueError('The expanded workbook exceeds 100 MB.')
        with pd.ExcelFile(BytesIO(content), engine='openpyxl') as book:
            return book.sheet_names
    except Exception as exc:
        raise ValueError('Could not open workbook sheets. Use an unprotected .xlsx under the size limit.') from exc


def read_file(content, filename, sheet=None, header_row=1):
    if not content or len(content) > 20 * 1024 * 1024:
        raise ValueError('Choose a non-empty file under 20 MB.')
    if not 1 <= header_row <= 50:
        raise ValueError('The header must be within the first 50 rows.')
    try:
        if filename.lower().endswith('.xlsx'):
            with ZipFile(BytesIO(content)) as archive:
                if sum(i.file_size for i in archive.infolist()) > 100 * 1024 * 1024:
                    raise ValueError('The expanded workbook exceeds 100 MB. Export a smaller sheet as CSV.')
            with pd.ExcelFile(BytesIO(content), engine='openpyxl') as book:
                sheets = book.sheet_names
                raw = pd.read_excel(book, sheet_name=sheet or sheets[0], header=None, dtype=object, keep_default_na=False, nrows=50002)
        elif filename.lower().endswith('.csv'):
            decoded = content.decode('utf-8-sig')
            try:
                delimiter = csv.Sniffer().sniff('\n'.join(decoded.splitlines()[header_row-1:header_row+10]), delimiters=',;\t|').delimiter
            except csv.Error:
                delimiter = ','
            rows = list(csv.reader(StringIO(decoded), delimiter=delimiter))
            raw = pd.DataFrame(rows).fillna('')
            sheets = []
        else:
            raise ValueError('Choose .xlsx or UTF-8 .csv.')
    except (ValueError, UnicodeError, BadZipFile) as exc:
        raise ValueError('Could not read the file: ' + str(exc)) from exc
    except Exception as exc:
        raise ValueError('Could not open this workbook. Try an unprotected .xlsx or UTF-8 CSV export.') from exc
    if len(raw) <= header_row:
        raise ValueError('No records below this header. Choose another header row or worksheet.')
    if len(raw) > 50001:
        raise ValueError('Use at most 50,000 records per file in this version.')
    if raw.shape[1] > 100:
        raise ValueError('Use at most 100 columns in this version.')
    headers, counts = [], {}
    for i, item in enumerate(raw.iloc[header_row-1]):
        label = str(item).strip() or f'Unnamed column {i+1}'
        counts[label] = counts.get(label, 0) + 1
        headers.append(label if counts[label] == 1 else f'{label} [column {i+1}]')
    frame = raw.iloc[header_row:].copy().reset_index(drop=True)
    frame.columns = headers
    return frame, sheets


def number(value):
    """Dot decimal, properly grouped comma thousands, optional $ and parentheses."""
    if pd.isna(value) or str(value).strip() in ('', '-', '—', 'N/A', 'n/a'):
        return None
    raw = str(value).strip()
    neg = raw.startswith('(') and raw.endswith(')')
    raw = raw[1:-1] if neg else raw
    raw = re.sub(r'\s+CAD$', '', raw, flags=re.I).strip()
    raw = re.sub(r'^(?:CAD\s*|\$\s*)', '', raw, flags=re.I).strip()
    if not re.fullmatch(r'[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?', raw):
        raise ValueError('Use a number such as 1234.50 or 1,234.50; no currency conversion is performed.')
    out = float(raw.replace(',', '')) * (-1 if neg else 1)
    if not abs(out) <= 1e12:
        raise ValueError('Amount exceeds the supported range.')
    return out


def month(value, order='ISO / year first'):
    if isinstance(value, (datetime, date, pd.Timestamp)) and not pd.isna(value):
        return pd.Timestamp(value).to_period('M').to_timestamp()
    text = str(value).strip()
    formats = ['%Y-%m', '%Y-%m-%d', '%Y/%m/%d', '%Y-%m-%d %H:%M:%S', '%Y-%m-%dT%H:%M:%S']
    formats += {'Day first': ['%d/%m/%Y', '%d-%m-%Y'], 'Month first': ['%m/%d/%Y', '%m-%d-%Y']}.get(order, [])
    for fmt in formats:
        try:
            return pd.Timestamp(datetime.strptime(text, fmt)).to_period('M').to_timestamp()
        except ValueError:
            pass
    raise ValueError('Missing or unrecognised date. Choose the date order or use YYYY-MM-DD / YYYY-MM.')


def analyse(frame, mapping, mode='Monthly summary', expense_field='other', order='ISO / year first', header_row=1, today=None, negative_expenses=False):
    fields = FINANCIAL if mode == 'Monthly summary' else ['amount']
    selected = [v for v in mapping.values() if v]
    if not mapping.get('period'):
        raise ValueError('Choose the date / month column.')
    if len(selected) != len(set(selected)):
        raise ValueError('A source column cannot be used for more than one field.')
    if any(c not in frame.columns for c in selected):
        raise ValueError('A mapped column no longer exists. Review the column choices.')
    if not any(mapping.get(f) for f in fields):
        raise ValueError('Choose at least one financial amount column.')
    today = pd.Timestamp(today or date.today()).to_period('M').to_timestamp()
    records, issues = [], []
    for pos, (_, row) in enumerate(frame.iterrows()):
        item = {'source_row': pos+header_row+1, 'period': pd.NaT}
        try:
            item['period'] = month(row[mapping['period']], order)
            if item['period'] >= today:
                raise ValueError('Current or future month: this baseline uses completed historical months only.')
        except ValueError as exc:
            issues.append({'Source row': item['source_row'], 'Field': 'period', 'Issue': str(exc)})
            item['period'] = pd.NaT
        for f in fields:
            target = f if mode == 'Monthly summary' else 'revenue' if mode == 'Sales transactions' else expense_field
            item[target] = None
            if not mapping.get(f):
                continue
            try:
                value = number(row[mapping[f]])
                if value is None:
                    raise ValueError('Missing amount; this field-month stays unknown, not zero.')
                if mode == 'Expense transactions' and negative_expenses:
                    value *= -1
                if mode == 'Monthly summary' and value < 0:
                    raise ValueError('Negative monthly total: review refunds/credits before using this month.')
                item[target] = value
            except ValueError as exc:
                issues.append({'Source row': item['source_row'], 'Field': target, 'Issue': str(exc)})
        records.append(item)
    rows = pd.DataFrame(records)
    mapped_fields = [f for f in FINANCIAL if f in rows and (mapping.get(f) if mode == 'Monthly summary' else True)]
    duplicate = frame.astype(str).duplicated(keep=False)
    # Duplicate summary months are ambiguous even if row values differ.
    dup_month = rows['period'].notna() & rows['period'].duplicated(keep=False) if mode == 'Monthly summary' else pd.Series(False, index=rows.index)
    blocked = duplicate | dup_month
    for i in rows.index[blocked]:
        issues.append({'Source row': int(rows.loc[i, 'source_row']), 'Field': 'row',
                       'Issue': 'Possible duplicate record / repeated summary month. Resolve or confirm separate transactions before combining.'})
    grouped = []
    for period, group in rows.dropna(subset=['period']).groupby('period'):
        entry = {'period': period}
        for field in mapped_fields:
            vals = group[field]
            entry[field] = float(vals.sum()) if vals.notna().all() and not blocked.loc[group.index].any() else float('nan')
            if pd.notna(entry[field]) and entry[field] < 0:
                entry[field] = float('nan')
                issues.append({'Source row': ', '.join(str(int(x)) for x in group.source_row), 'Field': field, 'Issue': 'Net monthly amount is negative; review the sign convention or credits.'})
        grouped.append(entry)
    monthly = pd.DataFrame(grouped, columns=['period']+mapped_fields)
    # Unknown-date amounts could belong to any month: do not certify those field totals.
    if rows.period.isna().any():
        for field in mapped_fields:
            monthly[field] = float('nan')
    return {'rows': rows, 'monthly': monthly, 'issues': pd.DataFrame(issues, columns=['Source row','Field','Issue']),
            'ignored': [c for c in frame.columns if c not in selected], 'mapped_fields': mapped_fields}


def combine(results):
    """Never add overlapping sources automatically (e.g. totals and transactions)."""
    values, conflicts = {}, []
    for source, result in results:
        for _, row in result['monthly'].iterrows():
            for field in result['mapped_fields']:
                key = (row['period'], field)
                if key in values:
                    conflicts.append({'Month': str(row['period'].date()), 'Field': field, 'Sources': values[key][1] + ' / ' + source})
                    values[key] = (float('nan'), values[key][1] + ' / ' + source)
                else:
                    values[key] = (row[field], source)
    months = sorted({k[0] for k in values})
    monthly = pd.DataFrame([{'period': m, **{f: values.get((m,f), (float('nan'),''))[0] for f in FINANCIAL}} for m in months], columns=['period']+FINANCIAL)
    return monthly, pd.DataFrame(conflicts)


def baseline(monthly):
    out, coverage = {}, []
    for field in FINANCIAL:
        known = monthly.dropna(subset=[field]) if field in monthly else pd.DataFrame()
        out[field] = float(known[field].mean()) if len(known) else None
        coverage.append({'Field': FIELDS[field], 'Complete months': len(known), 'Average per complete month': out[field],
                         'Months used': ', '.join(known.period.dt.strftime('%Y-%m')) if len(known) else 'None'})
    pairs = monthly.dropna(subset=['revenue','cogs']) if len(monthly) else pd.DataFrame()
    out['cogs_ratio'] = float(pairs.cogs.sum()/pairs.revenue.sum()) if len(pairs) and pairs.revenue.sum() > 0 else None
    return out, pd.DataFrame(coverage)


def safe_csv(frame):
    """Neutralize spreadsheet formulas in user-controlled text exports."""
    out = frame.copy()
    for col in out.columns:
        out[col] = out[col].map(lambda x: "'"+x if isinstance(x,str) and x.lstrip().startswith(('=', '+', '-', '@')) else x)
    return out.to_csv(index=False).encode('utf-8-sig')


from dataclasses import dataclass, asdict
import math
import pandas as pd


@dataclass(frozen=True)
class Plan:
    monthly_revenue: float = 0
    cogs_ratio: float = 0.30
    payroll: float = 0
    rent: float = 0
    other: float = 0
    capex: float = 0
    deposit_inventory_fees: float = 0
    equity: float = 0
    loan: float = 0
    interest: float = 0.08
    term: int = 60
    delay: int = 0
    delay_staff: float = .25
    delay_other: float = .50
    annual_growth: float = .05
    annual_inflation: float = .03
    maintenance: float = 250
    reserve: float = 20000
    ramp_months: int = 6
    ramp_start: float = .60
    start: str = '2027-01-01'
    seasonality: tuple = (1.,)*12


def validate(plan):
    for name, value in asdict(plan).items():
        if name in ('start','seasonality'):
            continue
        if not isinstance(value, (int,float)) or isinstance(value,bool) or not math.isfinite(value):
            raise ValueError(f'{name} must be a finite number.')
    for key in ['monthly_revenue','payroll','rent','other','capex','deposit_inventory_fees','equity','loan','maintenance','reserve']:
        if not 0 <= getattr(plan,key) <= 1e12:
            raise ValueError(f'{key} must be between 0 and one trillion.')
    for key in ['cogs_ratio','interest','delay_staff','delay_other','ramp_start']:
        if not 0 <= getattr(plan,key) <= 1:
            raise ValueError(f'{key} must be between 0 and 100%.')
    for key in ['annual_growth','annual_inflation']:
        if not -.5 <= getattr(plan,key) <= 1:
            raise ValueError(f'{key} must be between -50% and 100%.')
    for key, low, high in [('term',1,360),('delay',0,12),('ramp_months',0,24)]:
        val=getattr(plan,key)
        if int(val)!=val or not low<=val<=high:
            raise ValueError(f'{key} must be a whole number from {low} to {high}.')
    if len(plan.seasonality)!=12 or any(not math.isfinite(float(x)) or x<0 for x in plan.seasonality) or sum(plan.seasonality)<=0:
        raise ValueError('Provide 12 non-negative seasonal factors with a positive total.')
    start=pd.Timestamp(plan.start)
    if pd.isna(start) or start.day!=1:
        raise ValueError('The forecast must start on the first day of a month.')


def payment(principal, annual_rate, months):
    r=annual_rate/12
    return principal/months if r==0 else principal*r/(-math.expm1(-months*math.log1p(r)))


def forecast(plan, revenue_factor=1.0, payroll_factor=1.0):
    validate(plan)
    if any(not math.isfinite(x) or x<0 for x in (revenue_factor,payroll_factor)):
        raise ValueError('Scenario multipliers must be non-negative finite numbers.')
    debt=plan.loan
    opening=plan.equity+plan.loan-plan.capex-plan.deposit_inventory_fees
    cash=opening
    monthly_payment=payment(plan.loan,plan.interest,plan.term)
    seasons=[x/(sum(plan.seasonality)/12) for x in plan.seasonality]
    rows=[]
    for i, period in enumerate(pd.date_range(plan.start,periods=36,freq='MS')):
        opened=i>=plan.delay
        age=i-plan.delay
        ramp=(plan.ramp_start+(1-plan.ramp_start)*min(age/max(plan.ramp_months-1,1),1)) if opened and plan.ramp_months>1 else 1
        yr=i//12
        revenue=plan.monthly_revenue*revenue_factor*(1+plan.annual_growth)**yr*seasons[period.month-1]*ramp if opened else 0
        cogs=revenue*plan.cogs_ratio
        inflation=(1+plan.annual_inflation)**yr
        payroll=plan.payroll*payroll_factor*inflation*(1 if opened else plan.delay_staff)
        rent=plan.rent*inflation
        other=plan.other*inflation*(1 if opened else plan.delay_other)
        ebitda=revenue-cogs-payroll-rent-other
        interest=debt*plan.interest/12 if debt>0 else 0
        principal=(debt if i==plan.term-1 else min(debt,max(0,monthly_payment-interest))) if i<plan.term else 0
        debt=max(0,debt-principal)
        maintenance=plan.maintenance if opened else 0
        depreciation=plan.capex/60 if opened else 0
        net=ebitda-interest-principal-maintenance
        cash+=net
        fixed=payroll+rent+other+interest+principal+maintenance
        breakeven=fixed/(1-plan.cogs_ratio) if plan.cogs_ratio<1 else float('nan')
        rows.append({'Month':period,'Open':opened,'Revenue':revenue,'COGS':cogs,'Payroll':payroll,'Rent':rent,'Other costs':other,
                     'EBITDA':ebitda,'Depreciation':depreciation,'Interest':interest,'Pre-tax profit':ebitda-depreciation-interest,
                     'Loan principal':principal,'Debt balance':debt,'Maintenance spending':maintenance,'Net cash flow':net,'Closing cash':cash,
                     'Cash break-even revenue':breakeven})
    df=pd.DataFrame(rows)
    minimum=min(opening,df['Closing cash'].min())
    summary={'Opening cash':opening,'Year 1 revenue':df.Revenue.iloc[:12].sum(),'Year 1 EBITDA':df.EBITDA.iloc[:12].sum(),
             'Year 1 pre-tax profit':df['Pre-tax profit'].iloc[:12].sum(),'Year 1 net cash flow':df['Net cash flow'].iloc[:12].sum(),
             'Lowest cash (including opening)':minimum,'Extra funding to maintain reserve':max(0,plan.reserve-minimum),
             'Month 36 cash':cash,'Monthly loan payment':monthly_payment}
    return df,summary


def report(plan, summaries, source_notes):
    lines=['# Expansion feasibility report','', 'Illustrative forecast in CAD. Historical data is not proof of future demand.',
           'No tax, sales-tax timing, working-capital changes, cannibalization, terminal value or owner distributions are modelled.',
           'Amounts are received/paid in the same month. Funding and initial uses occur before month 1. No automatic gap borrowing.',
           'Depreciation uses 60 months; maintenance spending has no additional depreciation in this simplified model.',
           'Seasonality is normalized to average 1; growth/inflation step every 12 forecast months. Delay does not extend the horizon.',
           '', '## Data review',source_notes,'','## Confirmed assumptions']
    lines += [f'- {k}: {v}' for k,v in asdict(plan).items()]
    for name,summary in summaries.items():
        lines+=['',f'## {name}']+[f'- {k}: CAD {v:,.2f}' for k,v in summary.items()]
    lines+=['','## Before committing','Validate local demand and purchase mix; obtain lease and supplier quotes; confirm funding and opening dates; obtain a tax-aware forecast.']
    return '\n'.join(lines)


from dataclasses import asdict
from hashlib import sha256
from pathlib import Path
import json

import pandas as pd
import plotly.graph_objects as go
import streamlit as st


ROOT=Path(__file__).resolve().parent


def digest(value):
    return sha256(str(value).encode()).hexdigest()[:16]


def money(value):
    return f'${value:,.0f}'


def prepare():
    st.subheader('Bring your business history')
    st.write('Upload financial records from one existing location. Start with a monthly summary, or separate sales and expense files.')
    source=st.radio('Choose a starting point',['Try the café example','Upload company files'],horizontal=True)
    if source=='Try the café example':
        uploads=[('cafe_monthly_demo.csv', b'Reporting Month,Net Takings,Ingredient Costs,Staff Costs,Occupancy Costs,Other Expenses\n2025-10,39000,11700,14000,6200,2800\n2025-11,37500,11250,14000,6200,2800\n2025-12,42500,12750,14800,6200,3100\n2026-01,34000,10200,14000,6200,2700\n2026-02,36000,10800,14000,6200,2700\n2026-03,40000,12000,14000,6200,2800\n2026-04,42000,12600,14200,6200,2800\n2026-05,44000,13200,14200,6200,2800\n2026-06,46000,13800,14500,6200,3000\n2026-07,47000,14100,14500,6200,3000\n2026-08,46500,13950,14500,6200,3000\n2026-09,42500,12750,14200,6200,2800\n')]
        st.info('Fictional practice data. These are not actual company results or the earlier Excel model’s forecast.')
    else:
        files=st.file_uploader('Excel or CSV · up to 5 files · 20 MB each',type=['xlsx','csv'],accept_multiple_files=True)
        if not files:
            st.info('Choose a file above. A monthly summary can contain Month, Revenue, COGS, Payroll, Rent and Other expenses; your headings can differ.')
            return None
        if len(files)>5:
            st.error('Choose at most five files for this first version.'); return None
        uploads=[(f.name,f.getvalue()) for f in files]
    st.caption('Session-only processing: this app does not write uploads to disk or send them to an AI provider. Downloads are yours to save. Use one currency and one location; no currency conversion is performed.')
    currency=st.selectbox('Currency of every uploaded amount',['CAD','Other / mixed currencies'])
    if currency!='CAD':
        st.warning('This first version calculates in CAD. Convert the records consistently outside the app before using the forecast.'); return None
    selected_sources=[]
    for pos,(filename,content) in enumerate(uploads):
        uploadkey=digest(content)+f'_{pos}'
        st.success(f'✓ Uploaded · {filename}')
        if filename.lower().endswith('.xlsx'):
            try:
                available=sheet_names(content)
            except ValueError as exc:
                st.error(str(exc)); return None
            chosen=st.multiselect(f'Worksheets to analyse — {filename}',available,
                                  default=available if len(available)==1 else [],key='sheets_'+uploadkey)
            st.caption('Choose the financial sheets to combine. Leave README, verification totals and issue lists unselected. Choose either original records or a stress-test copy, never both.')
            for sheet in chosen:
                selected_sources.append((filename,content,sheet,uploadkey+'_'+digest(sheet)))
        else:
            selected_sources.append((filename,content,None,uploadkey))
    if not selected_sources:
        st.info('Select at least one financial worksheet above to continue.'); return None
    if len(selected_sources)>10:
        st.warning('Select at most 10 financial sheets/tables for one analysis.'); return None
    all_results=[]; notes=[]; signatures=[]; issue_frames=[]; audit_frames=[]
    incomplete=False
    for filename,content,sheet,key in selected_sources:
        source_label=f'{filename} / {sheet}' if sheet else filename
        with st.expander(f'Review · {source_label}',expanded=True):
            header=int(st.number_input('Header row number',1,50,1,key='header_'+key))
            try:
                raw,_=read_file(content,filename,sheet,header)
            except ValueError as exc:
                st.error(str(exc)); incomplete=True; continue
            filekey=key+'_'+digest((sheet,header))
            mode_hint,expense_hint=table_hint(sheet or filename)
            modes=['Monthly summary','Sales transactions','Expense transactions']
            mode=st.selectbox('What does this table contain?',modes,index=modes.index(mode_hint),key='mode_'+filekey)
            st.caption('Table type/category may be suggested from the sheet name. Confirm their meaning for your business.')
            st.caption('Monthly summary: one row per month. Transaction files: one row per sale/payment, with net CAD amounts. Do not include subtotal/grand-total rows. One expense table must contain a single cost category; mixed-category ledgers are not yet supported.')
            expense='other'; negative=False
            if mode=='Expense transactions':
                expense=st.selectbox('Expense category for every row in this table',COSTS,index=COSTS.index(expense_hint),format_func=lambda x:FIELDS[x],key='expense_'+filekey)
                negative=st.checkbox('Expenses are negative and refunds are positive in this file',key='sign_'+filekey)
            order=st.selectbox('Date format',['ISO / year first','Day first','Month first'],key='order_'+filekey)
            fields=['period']+(FINANCIAL if mode=='Monthly summary' else ['amount'])
            draft,evidence=suggestions(raw,fields)
            st.markdown('**Review column matches**')
            st.caption('Suggestions use heading synonyms, not AI guesses. A blank match means the meaning needs your choice. Manual choices remain in place for this file.')
            with st.expander('Why these matches were suggested'):
                st.dataframe(evidence,hide_index=True,width='stretch')
            mapping={}
            columns=st.columns(2)
            for i,field in enumerate(fields):
                with columns[i%2]:
                    options=[None]+list(raw.columns)
                    mapping[field]=st.selectbox(FIELDS[field],options,index=options.index(draft[field]),format_func=lambda x:'Not provided / choose a column' if x is None else x,key=f'map_{filekey}_{mode}_{field}')
            st.markdown('**Review or correct source values**')
            st.caption('Edits affect this session only. In the original file, use a unique reference column to distinguish genuinely separate identical transactions. Every source row remains visible. Remove subtotal rows in the original file and reupload after confirming they are not transactions.')
            edited=st.data_editor(raw.astype(str),num_rows='fixed',hide_index=False,width='stretch',key='edit_'+filekey)
            try:
                result=analyse(edited,mapping,mode,expense,order,header,negative_expenses=negative)
            except ValueError as exc:
                st.warning(str(exc)); incomplete=True; continue
            issue_count=len(result['issues'])
            st.write(f"{len(raw):,} source rows · {issue_count:,} review notes")
            if issue_count:
                st.warning('Analysis remains available, but affected monthly totals are unknown. Missing amounts do not become zero. A missing/invalid date makes every mapped financial total in this file uncertain until corrected.')
                st.dataframe(result['issues'],hide_index=True,width='stretch')
                issues=result['issues'].copy(); issues.insert(0,'Source',source_label); issue_frames.append(issues)
            else:
                st.success('Format checks passed. This checks dates, numeric values and possible duplicates; it does not prove completeness, correct accounting classification or business accuracy.')
            st.caption('Ignored columns: '+(', '.join(result['ignored']) or 'None')+'. Ignored columns do not contribute to the calculation.')
            audit=result['rows'].copy(); audit.insert(0,'Source',source_label); audit_frames.append(audit)
            signatures.append((source_label,header,edited.to_csv(index=False),mapping,mode,expense,order,negative))
            all_results.append((source_label,result))
            notes.append(f'{source_label}: {len(raw)} rows, {issue_count} review notes; ignored columns: {result["ignored"]}; type: {mode}; mapping: {mapping}; expense category: {expense}; negative expenses: {negative}; dates: {order}.')
    if incomplete:
        st.info('Finish the date and amount matches in every selected table, or deselect that sheet above. All selected tables must be reviewed before combining.'); return None
    monthly,conflicts=combine(all_results)
    if len(conflicts):
        st.warning('Overlapping file or sheet totals were not added together. The affected field-months are unknown to avoid double counting. Remove the overlapping source or upload a consolidated file.')
        st.dataframe(conflicts,hide_index=True,width='stretch')
    st.subheader('What your history supports')
    st.caption('Blank means unknown. A partial month is never presented as a complete total. Rows stay in the source review; only complete field-months support the suggested averages.')
    st.dataframe(monthly,hide_index=True,width='stretch',column_config={'period':st.column_config.DateColumn('Month',format='YYYY-MM'),**{f:st.column_config.NumberColumn(FIELDS[f],format='$ %.2f') for f in FINANCIAL}})
    base,coverage=baseline(monthly)
    st.dataframe(coverage,hide_index=True,width='stretch',column_config={'Average per complete month':st.column_config.NumberColumn(format='$ %.2f')})
    if len(monthly)>1:
        gaps=len(pd.date_range(monthly.period.min(),monthly.period.max(),freq='MS'))-len(monthly)
        if gaps: st.warning(f'{gaps} whole calendar month(s) are absent between the earliest and latest records. No revenue or expense is assumed for those missing months.')
    if any(coverage['Complete months']<12):
        st.info('At least one category has fewer than 12 complete months. Seasonal patterns and annual comparisons cannot be established reliably from this selection; forecast seasonality is an explicit assumption.')
    st.download_button('Download monthly data review',safe_csv(monthly),'expansion_monthly_review.csv','text/csv')
    st.download_button('Download all standardized source rows',safe_csv(pd.concat(audit_frames,ignore_index=True)),'expansion_source_audit.csv','text/csv')
    if issue_frames:
        st.download_button('Download review notes',safe_csv(pd.concat(issue_frames,ignore_index=True)),'expansion_data_issues.csv','text/csv')
    notes.extend(['Coverage:\n'+coverage.to_string(index=False),'Overlapping totals:\n'+conflicts.to_string(index=False)])
    key=digest(signatures)
    if not st.checkbox('I reviewed the column meanings, date format, net amounts, one-location scope and data coverage.',key='review_'+key):
        st.info('Confirm the review above to build the expansion plan.'); return None
    return base,'\n\n'.join(notes),key


def plan_inputs(base,key):
    st.subheader('Design the next location')
    st.write('History suggests a starting point. These are editable planning assumptions for a new location, not a prediction that it will match the existing business.')
    def amount(label,name,default):
        if not 0 <= default <= 1e12:
            st.warning(f'{label}: the historical suggestion exceeds the supported range. Review source units and enter a planning amount.')
            default=0.
        return st.number_input(label,min_value=0.,max_value=1e12,value=float(round(default,2)),step=100.,key=f'plan_{key}_{name}')
    a,b,c=st.columns(3)
    with a:
        revenue=amount('Monthly sales at full trading level (CAD)','revenue',base['revenue'] or 0)
        ratio=base['cogs_ratio']
        ratio_default=min(100.,max(0.,100*ratio)) if ratio is not None else 30.
        if ratio is None or ratio>1:
            st.caption('COGS percentage needs your estimate. The 30% default is illustrative; values above 100% need accounting review.')
            ratio_default=30.
        cogs=st.number_input('Ingredients / goods as % of sales',0.,100.,float(round(ratio_default,2)),key='cogs_'+key)/100
        growth=st.number_input('Annual sales growth assumption (%)',-50.,100.,5.,key='growth_'+key)/100
    with b:
        payroll=amount('Monthly payroll incl. employer costs','payroll',base['payroll'] or 0)
        rent=amount('Monthly rent and occupancy','rent',base['rent'] or 0)
        other=amount('Other monthly operating costs','other',base['other'] or 0)
    with c:
        start=st.date_input('Forecast / funding start month',value=pd.Timestamp('2027-01-01').date(),key='start_'+key).replace(day=1)
        delay=st.number_input('Months until opening',0,12,0,key='delay_'+key)
        inflation=st.number_input('Annual fixed-cost increase (%)',-50.,100.,3.,key='inflation_'+key)/100
    unknown=[FIELDS[f] for f in FINANCIAL if base[f] is None]
    if unknown:
        st.warning('No usable historical average for: '+', '.join(unknown)+'. The zero entries are empty planning placeholders. Enter an estimate, or explicitly confirm the cost is genuinely zero below.')
    st.markdown('**Opening investment and funding**')
    a,b,c=st.columns(3)
    with a:
        capex=amount('Equipment and fit-out','capex',140494)
        initial=amount('Deposit, inventory and pre-opening fees','initial',35000)
        maintenance=amount('Monthly maintenance spending after opening','maintenance',250)
    with b:
        equity=amount('Owner equity available at start','equity',120494)
        loan=amount('Loan drawn at start','loan',120000)
        reserve=amount('Minimum cash reserve','reserve',20000)
    with c:
        interest=st.number_input('Loan annual interest (%)',0.,100.,8.,key='interest_'+key)/100
        term=st.number_input('Loan term (months)',1,360,60,key='term_'+key)
    st.caption('Opening investment/funding defaults are illustrative café assumptions, not extracted from your file. All funding is received and initial uses paid before month 1; interest and rent begin immediately.')
    with st.expander('Opening ramp, delay costs and seasonality'):
        ramp=st.number_input('Months to reach full sales level',0,24,6,key='ramp_'+key)
        ramp_start=st.number_input('First open month as % of full sales',0.,100.,60.,key='rampstart_'+key)/100
        staff=st.number_input('Payroll paid during delay (%)',0.,100.,25.,key='staffdelay_'+key)/100
        delay_other=st.number_input('Other fixed costs paid during delay (%)',0.,100.,50.,key='otherdelay_'+key)/100
        seasonal=st.checkbox('Use assumed seasonal factors',key='season_'+key)
        factors=(1.,)*12
        if seasonal:
            seasonal_df=st.data_editor(pd.DataFrame({'Month':pd.date_range('2027-01-01',periods=12,freq='MS').strftime('%b'), 'Factor':[.85,.9,.95,1.,1.05,1.1,1.1,1.1,1.05,1.,.95,.95]}),disabled=['Month'],hide_index=True,key='factors_'+key)
            factors=tuple(seasonal_df.Factor)
        st.caption('Seasonality defaults are hypothetical and are normalized to average 1. A 6-month ramp starts at 60% and rises evenly to 100%; 0 or 1 means full sales immediately. The horizon remains 36 months even with a delay.')
    return Plan(monthly_revenue=revenue,cogs_ratio=cogs,payroll=payroll,rent=rent,other=other,capex=capex,deposit_inventory_fees=initial,equity=equity,loan=loan,interest=interest,term=term,delay=delay,delay_staff=staff,delay_other=delay_other,annual_growth=growth,annual_inflation=inflation,maintenance=maintenance,reserve=reserve,ramp_months=ramp,ramp_start=ramp_start,start=str(start),seasonality=factors)


def results(plan,notes,key):
    signature=digest((key,asdict(plan)))
    st.caption('Pre-tax model: excludes sales-tax timing, changing inventory/receivables/payables, first-location cannibalization, owner distributions and terminal asset values. Profit and cash are different. No extra borrowing is invented to cover a shortfall.')
    approved=st.checkbox('I confirm these planning inputs, including any zero costs and illustrative defaults. I understand the missing-data notes.',key='approve_'+signature)
    if not approved: return
    if st.button('Analyse expansion plan',type='primary',key='run_'+signature):
        st.session_state['expansion_run']=signature
    if st.session_state.get('expansion_run')!=signature:
        st.info('Click Analyse expansion plan to calculate these reviewed inputs.'); return
    try:
        scenarios={name:forecast(plan,factor) for name,factor in [('Lower sales (−20%)',.8),('Expected inputs',1.),('Higher sales (+20%)',1.2)]}
    except (ValueError,TypeError) as exc:
        st.error('Please correct the planning input: '+str(exc)); return
    monthly,summary=scenarios['Expected inputs']
    st.subheader('Your decision brief')
    st.caption('The scenarios change sales and proportional goods costs only. Fixed costs stay the same. These are stress tests, not probabilities. “Year 1” means the first 12 forecast months.')
    a,b,c,d=st.columns(4)
    a.metric('Year 1 sales',money(summary['Year 1 revenue']))
    b.metric('Year 1 operating earnings',money(summary['Year 1 EBITDA']))
    c.metric('Lowest cash',money(summary['Lowest cash (including opening)']))
    d.metric('Additional reserve needed',money(summary['Extra funding to maintain reserve']))
    tabs=st.tabs(['Cash and scenarios','Monthly forecast','Action plan','How this was calculated','Download'])
    with tabs[0]:
        chart=pd.DataFrame({name:result[0]['Closing cash'].values for name,result in scenarios.items()},index=monthly.Month)
        # Include month-zero cash so an immediate funding shortfall is visible.
        chart.loc[monthly.Month.iloc[0]-pd.DateOffset(months=1)]=summary['Opening cash']
        chart=chart.sort_index(); chart['Minimum reserve']=plan.reserve
        figure=go.Figure()
        for column,color in zip(chart.columns,['#d87732','#2563eb','#16a3a0','#64748b']):
            figure.add_trace(go.Scatter(x=chart.index,y=chart[column],name=column,mode='lines',line={'color':color,'width':3,'dash':'dash' if column=='Minimum reserve' else 'solid'},hovertemplate='%{x|%b %Y}: $%{y:,.0f}<extra>%{fullData.name}</extra>'))
        figure.update_layout(height=420,paper_bgcolor='#ffffff',plot_bgcolor='#ffffff',font={'color':'#14233d'},margin={'l':10,'r':10,'t':20,'b':10},legend={'orientation':'h','y':-0.2},yaxis={'title':'Cash (CAD)','tickprefix':'$','fixedrange':True},xaxis={'title':None,'fixedrange':True})
        st.plotly_chart(figure,use_container_width=True,config={'scrollZoom':False,'displayModeBar':False})
        st.caption('First point is opening cash before trading. Negative cash is an unfunded gap; it is not an available bank balance.')
        st.dataframe(pd.DataFrame({n:s for n,(_,s) in scenarios.items()}),width='stretch',column_config={n:st.column_config.NumberColumn(format='$ %.2f') for n in scenarios})
    with tabs[1]:
        st.dataframe(monthly,hide_index=True,width='stretch',column_config={'Month':st.column_config.DateColumn(format='YYYY-MM'),**{c:st.column_config.NumberColumn(format='$ %.2f') for c in monthly.columns if c not in ('Month','Open')}})
    with tabs[2]:
        if summary['Extra funding to maintain reserve']>0:
            st.error('Funding review required: the expected-input case falls below your minimum reserve. Confirm additional funding or revise the investment, costs or timing before committing.')
        else:
            st.success('The expected-input case stays above the chosen reserve under these assumptions. This is not approval to invest or proof of demand.')
        down=scenarios['Lower sales (−20%)'][1]['Extra funding to maintain reserve']
        st.write(f'**Test demand:** the lower-sales case requires {money(down)} additional funding to preserve the reserve. Validate customer counts, average purchase and achievable capacity at the proposed site.')
        open_rows=monthly[monthly.Open]
        if len(open_rows):
            breakeven=open_rows['Cash break-even revenue'].iloc[-1]
            if pd.notna(breakeven): st.write(f'**Check break-even:** the last forecast month needs about {money(breakeven)} monthly sales to cover the modelled cash costs. This varies by month; see the full table.')
            else: st.warning('At a 100% goods-cost ratio, sales contribute nothing to fixed costs; no finite sales break-even is available.')
        st.write('**Verify costs:** obtain equipment, fit-out and lease quotes; confirm employer costs and identify omitted expense categories.')
        st.write('**Test timing:** increase Months until opening, confirm the revised assumptions, and rerun. Rent and loan payments continue during a delay.')
        st.write('**Resolve unknowns:** revisit the source review and replace missing values with verified data when available. Reuploading recalculates suggestions and requires a fresh review.')
    with tabs[3]:
        st.markdown('''- **Historical averages:** arithmetic mean of complete months for each category. Categories can use different months; the coverage table lists them.
- **Goods-cost percentage:** total goods cost ÷ total revenue across months with both values present. Otherwise an explicit assumption is required.
- **Sales:** full-trading monthly sales × scenario multiplier × normalized seasonal factor × opening ramp × annual growth. Zero during opening delay.
- **Operating earnings (EBITDA):** sales minus goods, payroll, rent and other costs.
- **Pre-tax profit:** operating earnings minus loan interest and straight-line depreciation of initial equipment/fit-out over 60 months.
- **Net cash flow:** operating earnings minus interest, loan principal and maintenance spending.
- **Closing cash:** previous cash plus net cash flow. Opening cash = equity + loan − equipment/fit-out − other initial uses.
- **Additional reserve needed:** chosen reserve minus the lowest cash balance (including opening), with a minimum of zero.
- **Cash break-even revenue:** monthly fixed costs, debt service and maintenance ÷ (1 − goods-cost percentage).''')
        st.caption('A fixed-payment amortizing loan is assumed. Deposit/inventory/fees are treated as initial cash uses, without subsequent recovery or profit charges. This simplified portfolio model is not a full set of financial statements.')
    with tabs[4]:
        summaries={n:s for n,(_,s) in scenarios.items()}
        st.download_button('Download monthly forecast (CSV)',safe_csv(monthly),'expansion_forecast.csv','text/csv')
        st.download_button('Download scenario comparison (CSV)',safe_csv(pd.DataFrame(summaries).reset_index(names='Metric')),'expansion_scenarios.csv','text/csv')
        st.download_button('Download recommendation and assumptions',report(plan,summaries,notes),'expansion_report.md','text/markdown')
        st.download_button('Download planning inputs (JSON)',json.dumps(asdict(plan),indent=2),'expansion_inputs.json','application/json')
        st.caption('CSV downloads open in Excel as values. An automatically generated formula-based workbook and PDF presentation are later milestones.')


